mapper.select:
SELECT o.id, o.buyer_id, o.seller_id, o.product_id, o.price, o.status, o.create_time, o.update_time, bu.nickname AS buyer_nickname, su.nickname AS seller_nickname, p.title AS product_title, EXISTS(SELECT 1 FROM review rv WHERE rv.order_id = o.id AND rv.reviewer_id = #{userId}) AS reviewed FROM orders o JOIN users bu ON o.buyer_id = bu.id JOIN users su ON o.seller_id = su.id JOIN product p ON o.product_id = p.id
o.seller_id = #{userId} o.buyer_id = #{userId}
AND o.status = #{status}
ORDER BY o.create_time DESC
